// Bolt sprites for mods, v1.0.0. GENERATED by brand/bolt-sprites/tools/build.py: edit design.py, not this file.
// Copy this file into your mod's hooks/ folder (mods install on their own, so they cannot import from brand/).
// Rules (brand/BRAND.md): pink is the antenna light only, blush the cheeks only. Never recolour, rotate or stretch.
// Never draw Bolt over a safety hold, and never in a toast (toasts are uncoloured text).

export const BOLT_PALETTE = {
  B: '#C8F53C',
  S: '#9BC21A',
  O: '#FF5C8A',
  K: '#FF8FB1',
  E: '#101114',
  W: '#FBFBF8',
  G: '#8E95A3',
} as const

export type BoltSize = 'small' | 'tiny'
export type BoltSmallPose = 'idle' | 'run1' | 'run2' | 'jump' | 'crash' | 'cheer' | 'sleep' | 'sweat' | 'think' | 'egg' | 'egg-wobble-l' | 'egg-wobble-r' | 'egg-crack-1' | 'egg-crack-2' | 'egg-crack-3' | 'egg-hatch'
export type BoltTinyPose = 'idle' | 'run1' | 'run2' | 'jump' | 'crash' | 'cheer' | 'sleep'
export type BoltPose = BoltSmallPose | BoltTinyPose

/** One text cell: a character and its colours (absent = the surface's own). */
export type BoltCell = { ch: string; fg?: string; bg?: string }

/** Pixel rows: one palette letter per pixel, '.' empty. Heights are even (two pixel rows per cell). */
export const BOLT_SPRITES = {
  small: {
    'idle': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'run1': ['...OO.....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBWEBBWEB', 'BBBEEBBEEB', 'BKKBBBBBKB', 'BBBBBEEBBB', '.SSSSSSSS.', 'SS......SS'],
    'run2': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBWEBBWEB', 'BBBEEBBEEB', 'BKKBBBBBKB', 'BBBBBEEBBB', '.SSSSSSSS.', '...SSSS...'],
    'jump': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEBBBB', '.SSSSSSSS.', '...S..S...'],
    'crash': ['......OO..', '.....S....', '..BBBBBB..', '.BBBBBBBB.', 'BEBEBBEBEB', 'BBEBBBBEBB', 'BEBEBBEBEB', 'BBBBEEBBBB', '.SSSSSSSS.', 'SS......SS'],
    'cheer': ['S...OO...S', 'S...SS...S', 'SBBBBBBBBS', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBEEEEBBB', '.SSSSSSSS.', '..SS..SS..'],
    'sleep': ['....SS....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBBBBBBBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBBBBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'sweat': ['....OO....', '....SS...G', '..BBBBBB.G', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEEBBB', '.SSSSSSSS.', '..SS..SS..'],
    'think': ['....OO....', '....SS....', '..BBBBBB..', '.BBWEBWEB.', 'BBBEEBEEBB', 'BBBBBBBBBB', 'BKKBBBBKKB', 'BBBBBEBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'egg': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BBBBBBBB.', '.BBBBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-wobble-l': ['...OO.....', '...SS.....', '..BWBB....', '.BWBBBB...', '.BBBBBB...', '.BBBBBBBB.', '.BBBBBBBB.', '.BBBBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-wobble-r': ['.....OO...', '.....SS...', '....BWBB..', '...BWBBBB.', '...BBBBBB.', '.BBBBBBBB.', '.BBBBBBBB.', '.BBBBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-crack-1': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BEBBBBBB.', '.BBEBBBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-crack-2': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BEBEBBBB.', '.BBEBEBBS.', '..BBBBBS..', '...SSSS...'],
    'egg-crack-3': ['....OO....', '....SS....', '...BWBB...', '..BWBBBB..', '..BBBBBB..', '.BBBBBBBB.', '.BEBEBEBB.', '.BBEBEBES.', '..BBBBBS..', '...SSSS...'],
    'egg-hatch': ['......OO..', '......SS..', '....BWBBBB', '....B.B.B.', '..........', '..........', '.B.B.B.BB.', '.BSSSSSSB.', '..BBBBBS..', '...SSSS...'],
  },
  tiny: {
    'idle': ['.O.', 'BEB', 'BBB', 'S.S'],
    'run1': ['.O.', 'BEB', 'BBB', 'S.S'],
    'run2': ['.O.', 'BEB', 'BBB', '.S.'],
    'jump': ['.O.', 'BEB', 'BBB', '.S.'],
    'crash': ['...', '.SO', 'BEB', 'SSS'],
    'cheer': ['SOS', 'BEB', 'BBB', 'S.S'],
    'sleep': ['.S.', 'BSB', 'BBB', 'S.S'],
  },
} as const

/** Letters drawn over a whole cell (cell coordinates). */
const GLYPHS: Record<string, readonly { row: number; col: number; ch: string; color: keyof typeof BOLT_PALETTE }[]> = {
  'small/sleep': [{ row: 0, col: 8, ch: 'z', color: 'G' }],
}

/** The two run frames, in order. Swap them about every 120 ms while running. */
export const BOLT_RUN = ['run1', 'run2'] as const

function colour(key: string | undefined): string | undefined {
  if (key === undefined || key === '.') return undefined
  return (BOLT_PALETTE as Record<string, string>)[key]
}

/**
 * Packs a pose into half-block text cells: rows / 2 lines of `cols` cells.
 * Terminal: draw with Raster (see hatchling's rasterCells). Desktop: one fixed-width cell per character.
 */
export function boltCells(size: 'small', pose: BoltSmallPose): BoltCell[][]
export function boltCells(size: 'tiny', pose: BoltTinyPose): BoltCell[][]
export function boltCells(size: BoltSize, pose: BoltPose): BoltCell[][] {
  const rows: readonly string[] = (BOLT_SPRITES[size] as Record<string, readonly string[]>)[pose] ?? []
  const out: BoltCell[][] = []
  for (let r = 0; r + 1 < rows.length; r += 2) {
    const top = rows[r] ?? ''
    const bottom = rows[r + 1] ?? ''
    const line: BoltCell[] = []
    for (let c = 0; c < top.length; c += 1) {
      const t = colour(top[c])
      const b = colour(bottom[c])
      if (t === undefined && b === undefined) line.push({ ch: ' ' })
      else if (b === undefined) line.push({ ch: '\u2580', fg: t })
      else if (t === undefined) line.push({ ch: '\u2584', fg: b })
      else if (t === b) line.push({ ch: '\u2588', fg: t })
      else line.push({ ch: '\u2580', fg: t, bg: b })
    }
    out.push(line)
  }
  for (const glyph of GLYPHS[`${size}/${pose}`] ?? []) {
    const line = out[glyph.row]
    if (line !== undefined && glyph.col < line.length) line[glyph.col] = { ch: glyph.ch, fg: BOLT_PALETTE[glyph.color] }
  }
  return out
}

/** Merges a row of cells into runs of one style, for coloured Text spans. */
export function boltRuns(line: readonly BoltCell[]): BoltCell[] {
  const runs: BoltCell[] = []
  for (const cell of line) {
    const last = runs[runs.length - 1]
    if (last !== undefined && last.fg === cell.fg && last.bg === cell.bg) last.ch += cell.ch
    else runs.push({ ...cell })
  }
  return runs
}

files.hooks/prices.ts:
// The built-in price table: USD per million tokens, per model family, as the
// published list prices stood on 2026-10-08.
//
// Claude Code's own cost ledger (what /cost shows) is preferred for the session
// total wherever it exists; this table prices the breakdowns (per category, per
// turn) and stands in for the total where no ledger is kept. Everything priced
// here is shown with "≈": it leaves out long-context premiums, fast mode,
// 1-hour cache writes, batch and regional pricing. A model with no row gets no
// price at all (tokens only), never a guess.

import type { RedlineTokens } from '../types'

export type Price = RedlineTokens

type Row = {
  label: string
  families: readonly string[]
  /** "major.minor", as the model id spells it (claude-opus-4-1 is 4.1). */
  versions: readonly string[]
  price: Price
  /** A second rate card for requests whose prompt is over 100k tokens. */
  above100k?: Price
}

// Cache writes are the 5-minute rate (1.25x input); cache reads 0.1x input
// unless the model's list price says otherwise.
const rates = (input: number, output: number, readX = 0.1): Price => ({
  input,
  output,
  cacheWrite: input * 1.25,
  cacheRead: input * readX,
})

export const PRICE_TABLE: readonly Row[] = [
  { label: 'Fable 5.1', families: ['fable', 'mythos'], versions: ['5.1'], price: rates(10, 50, 0.025) },
  { label: 'Fable 5', families: ['fable', 'mythos'], versions: ['5.0'], price: rates(10, 50) },
  { label: 'Opus 5.5', families: ['opus'], versions: ['5.5'], price: rates(4, 20, 0.05) },
  { label: 'Opus 4.5 - 5', families: ['opus'], versions: ['4.5', '4.6', '4.7', '4.8', '5.0'], price: rates(5, 25) },
  { label: 'Opus 4 - 4.1', families: ['opus'], versions: ['4.0', '4.1'], price: rates(15, 75) },
  { label: 'Sonnet 5 - 5.5', families: ['sonnet'], versions: ['5.0', '5.5'], price: rates(2, 10) },
  { label: 'Sonnet 4 - 4.6', families: ['sonnet'], versions: ['4.0', '4.5', '4.6'], price: rates(3, 15) },
  { label: 'Haiku 5.5', families: ['haiku'], versions: ['5.5'], price: rates(0.1, 0.5), above100k: rates(0.5, 2.5) },
  { label: 'Haiku 4.5', families: ['haiku'], versions: ['4.5'], price: rates(1, 5) },
]

// claude-opus-4-1-20250805, us.anthropic.claude-sonnet-4-5-20250929-v1:0,
// claude-haiku-4-5@20251001, claude-opus-5: the family, then the major, then a
// one-digit minor when one follows (a date is never a minor).
const MODEL_ID = /(opus|sonnet|haiku|fable|mythos)-(\d+)(?:-(\d)(?!\d))?/

/** The price row for a model id, or undefined when the table has none. */
export function priceRow(model: string): Row | undefined {
  const m = MODEL_ID.exec(model.toLowerCase())
  if (!m) return undefined
  const family = m[1] ?? ''
  const version = `${m[2]}.${m[3] ?? '0'}`
  return PRICE_TABLE.find(row => row.families.includes(family) && row.versions.includes(version))
}

/** What one request cost per category, USD; undefined for an unpriced model. */
export function priceRequest(model: string, t: RedlineTokens): RedlineTokens | undefined {
  const row = priceRow(model)
  if (!row) return undefined
  const prompt = t.input + t.cacheRead + t.cacheWrite
  const p = row.above100k && prompt > 100_000 ? row.above100k : row.price
  return {
    input: (t.input * p.input) / 1e6,
    output: (t.output * p.output) / 1e6,
    cacheRead: (t.cacheRead * p.cacheRead) / 1e6,
    cacheWrite: (t.cacheWrite * p.cacheWrite) / 1e6,
  }
}

export const sumTokens = (t: RedlineTokens): number => t.input + t.output + t.cacheRead + t.cacheWrite

files.types/index.d.ts:
// The values redline keeps in $.state: the gauge every drawing reads, and
// whether the band above the prompt is on. Self-contained on purpose: no
// import, every name led by "Redline".

/** The four token counts of a model request, as the API reports them. */
export type RedlineTokens = {
  input: number
  output: number
  cacheRead: number
  cacheWrite: number
}

/** One reading over time: context tokens, or new tokens of one request. */
export type RedlineSample = { t: number; tokens: number }

/** One plan rate-limit window as Claude Code reports it. */
export type RedlineLimit = {
  kind: string
  percentUsed: number
  resetsAt?: string
}

/** One turn (or one subagent run) and what its requests used. */
export type RedlineTurn = {
  id: string
  label: string
  isSubagent: boolean
  startedAt: number
  requests: number
  tokens: RedlineTokens
  /** USD by the built-in price table; null once a request had no price. */
  usd: number | null
}

/** What the requests charged to one kind of work, or to one model, used. */
export type RedlineSpend = {
  requests: number
  tokens: RedlineTokens
  /** USD by the built-in price table; null once a request charged here had no price. */
  usd: number | null
}

export type RedlineGauge = {
  /** When the session began (Claude Code's own figure), epoch ms. */
  sessionStartedAt: number | null
  /** When redline began counting tokens, epoch ms. */
  trackingSince: number | null
  /** The model's context window in tokens, from Claude Code. */
  window: number | null
  /** Input side of the main loop's last request; null while unknown. */
  contextTokens: number | null
  /**
   * Claude Code's own fill percentage (the status line's used_percentage)
   * when it reported one for this reading; null to compute it from tokens.
   */
  contextPercent: number | null
  /** Main-loop context readings of the last 10 minutes (pace). */
  samples: RedlineSample[]
  /** New tokens per request of the last 10 minutes (tokens per minute). */
  flow: RedlineSample[]
  /** Every request counted since trackingSince, main loop and subagents. */
  totals: RedlineTokens
  /** The same requests priced by the built-in table, per category, USD. */
  tableUsd: RedlineTokens
  /** Models seen with no row in the price table. */
  unpriced: string[]
  /** Claude Code's own cost ledger for the session, USD; null where absent. */
  ledgerUsd: number | null
  limits: RedlineLimit[]
  /** Each plan window's readings of the last 15 minutes, by kind (run-out). */
  limitHistory: Record<string, RedlineSample[]>
  turns: RedlineTurn[]
  /**
   * This session's requests by the kind of work each carried (the results of the
   * previous response's tool calls: reading, editing, shell, search, planning; a
   * subagent's requests as subagents; a turn's first request as prompt; one with no
   * results as answering; an MCP server's tools as mcp:<server>), a request carrying
   * several kinds split evenly across them.
   */
  spend: Record<string, RedlineSpend>
  /** The same requests by the model that answered. */
  byModel: Record<string, RedlineSpend>
  /** The model of the main loop's last request. */
  model: string | null
  /** The 80% toast may fire; false until context drops under 75%. */
  isArmed: boolean
}

/** Which of the pane's two views is open: the limits, or where the money went. */
export type RedlineView = 'overview' | 'spend'

declare module 'claude-code' {
  interface PluginState {
    redline: { gauge: RedlineGauge; isBandOn: boolean; view: RedlineView }
  }
}
